from pathlib import Path
from lxml import etree as E
import fitz,zipfile,re,json,hashlib,subprocess

B=Path(__file__).resolve().parent;OUT=B.parent.parent;ROOT=OUT.parents[1]
names=['SMA_Major_Project_Report_10_Pages.docx','SMA_Major_Project_Report_10_Pages.pdf','SMA_Major_Project_Presentation.pptx','SMA_Major_Project_Presentation.pdf','SMA_Major_Project_Demo.mp4']
report=fitz.open(OUT/names[1]);deck=fitz.open(OUT/names[3]);assert len(report)==10;assert len(deck)==11
expected=['1  Introduction','2  Literature Survey and Research Gaps','3  Literature Survey and Research Gaps','4  Problem Definition Objectives and Scope','5  System Architecture and Data Flow','6  Implementation and Important Algorithms','7  Application Outputs and Scenario Results','8  Evaluation and Further Application Outputs','9  Conclusion and Future Scope','10  References']
pages=[]
for i,p in enumerate(report):
 txt=p.get_text();assert expected[i] in txt, (i+1,expected[i]);assert len(txt.strip())>500
 p.get_pixmap(matrix=fitz.Matrix(1.7,1.7)).save(B/f'report_qa/page-{i+1}.png')
 pages.append({'page':i+1,'heading':expected[i],'text_characters':len(txt),'images':len(p.get_images())})
z=zipfile.ZipFile(OUT/names[2]);ns={'a':'http://schemas.openxmlformats.org/drawingml/2006/main','p':'http://schemas.openxmlformats.org/presentationml/2006/main'}
slideparts=[f for f in z.namelist() if re.fullmatch(r'ppt/slides/slide\d+\.xml',f)];assert len(slideparts)==11
texts='\n'.join(z.read(f).decode('utf-8','ignore') for f in z.namelist() if f.endswith('.xml'))
for s in ['Atomix','Unity','chemistry','Phadke','Dhir','Inworld','Blender','Virnodkar','video','QR code']:
 assert not re.search(s,texts,re.I),s
assert not any(f.startswith('ppt/media/') and re.search(r'\.(mp4|avi|wmv|mov)$',f,re.I) for f in z.namelist())
for s in ['Dr. Nilesh Yadav','Kartik Verma','Kushal Soni']:assert s in texts
pres=E.fromstring(z.read('ppt/presentation.xml'));assert pres.find('p:sldSz',ns).attrib=={'cx':'12192000','cy':'6858000'}
original=OUT/'dump/LY_Major Project (1).pptx';backup=OUT/'dump/Original_LY_Major_Project_Template.pptx';assert original.read_bytes()==backup.read_bytes()
video=json.loads((B/'video_validation.json').read_text());assert 120<=video['seconds']<=180 and video['full_decode_passed'];assert not video['browser_errors']
files=[{'path':str(OUT/n),'bytes':(OUT/n).stat().st_size,'sha256':hashlib.sha256((OUT/n).read_bytes()).hexdigest()}for n in names]
validation={'report_pages':10,'report_allocation':pages,'presentation_slides':11,'slide_dimensions_emu':[12192000,6858000],'names_verified':['Dr. Nilesh Yadav','Kartik Verma','Kushal Soni'],'old_project_content_scan':'pass, including speaker notes','presentation_media':'Only template branding, architecture diagram, and actual screenshot crops','template_backup_hash_match':True,'video':video,'files':files,'rendering':'Native Word and PowerPoint exports, with all report pages and slides visually reviewed','software_tests':'23 existing tests passed','source_changes':'No tracked source or runtime files modified','blockers':[]}
(B/'final_validation.json').write_text(json.dumps(validation,indent=2))
lines=['# SMA major project deliverables','', 'All final files are in this folder. Nothing has been committed or published.','', '## Final files','']
for f in files:lines.append('- `'+f['path']+'`')
lines += ['', '## Validation', '', '- Report: exactly 10 pages confirmed in Word and in the exported PDF.', '- Allocation: introduction on page 1; literature and gaps on pages 2-3; problem, objectives, and scope on page 4; architecture and implementation on pages 5-6; outputs and evaluation on pages 7-8; conclusion and future scope on page 9; references on page 10.', '- Every report page and all 11 presentation slides were rendered and visually checked.', '- Presentation preserves the supplied 13.3333 x 7.5 inch template, theme, masters, Somaiya branding, red borders, and Times New Roman typography.', '- Editable native text and tables are retained in the presentation. Diagrams and screenshots are embedded images.', '- Guide: Dr. Nilesh Yadav. Students: Kartik Verma and Kushal Soni.', '- Old-project text, images, references, and attributions were replaced. No presentation video section, video link, video embed, or QR code remains.', '- Demo: 148.17 seconds (2 minutes 28 seconds), 1920 x 1080, H.264, captioned without an audio narration track. All 889 frames decoded successfully.', '- Demo records real Chrome interactions with the unchanged application. Browser capture reported no application errors.', '- All 23 existing application tests passed. Software tests do not establish field performance.', '- Results clearly distinguish agronomy-generated targets and scenario estimates from measured field outcomes.', '', '## Files preserved in dump', '', '- `LY_Major Project (1).pptx`: original unrelated-project presentation moved from the parent presentation folder after checking the backup SHA-256 hash.', '- `Original_LY_Major_Project_Template.pptx`: byte-identical backup retained before authoring.', '- `revision_1/`: superseded generated report and presentation drafts and their PDF exports, plus the original MPEG-4 video encode.', '- `template_preview/`: original template slide renders.', '- `build/`: reproducible authoring sources, actual browser captures, recording frames, assets, QA images, tool dependencies, and validation records.', '', 'Existing files in the repository report folder and the older SMA presentation in the parent presentation folder were left in place. No source code, models, dataset, or runtime dependencies were moved. No files were deleted.', '', '## Remaining items', '', 'No deliverable is blocked. Voice narration is optional; the finished demo uses captions. Field trials and live-data integrations remain future project work, as documented in the report.', '', '## Reproduction notes', '', 'Authoring and rendering sources are retained in dump/build. Native DrawingML editing preserved the PowerPoint template because the Artifact Tool runtime and dependency-loader tool were not exposed in this Windows session. The packaged DOCX renderer could not start because pdf2image was unavailable, so the report was rendered and page-counted through installed Word instead. The PowerShell Word COM binder stalled on export; export_word.vbs completed native PDF export successfully. These workarounds do not affect the delivered files.', '', 'Detailed hashes, page allocation, video checks, and source provenance are in dump/build/final_validation.json and dump/build/image_provenance.json.']
(OUT/'DELIVERABLES_AND_VALIDATION.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print(json.dumps({'report_pages':10,'slides':11,'video_seconds':video['seconds'],'template_backup_match':True,'files':files,'blockers':[]},indent=2))
